window.SCREEN_NOTES = {"23-01": {"s": "app", "sn": "S/N 23", "title": "Home: support entry point", "note": "New card shown only to users holding the Support role. Badge counts assignments with feedback outstanding."}, "23-02": {"s": "app", "sn": "S/N 23", "title": "Support role: assignments list", "note": "New section in My Activities, above the user's own registrations. Grouped by date; slot chips show only the tagged slot."}, "23-03": {"s": "app", "sn": "S/N 23", "title": "Support role: volunteer roster", "note": "Rule shown: the support user is excluded from their own roster. Each row pairs attendance and feedback status."}, "23-04": {"s": "app", "sn": "S/N 23", "title": "Support role: attendance QR", "note": "Full-screen code for the tagged slot only. Rotating code stops screenshots being reused."}, "23-05": {"s": "app", "sn": "S/N 23", "title": "Form: rating, chips, radio, text", "note": "Rendered from the Portal template. Fields marked \"Shared with volunteer\" are the only ones the volunteer later sees. Auto-saves as a draft."}, "23-06": {"s": "app", "sn": "S/N 23", "title": "Form: dropdown, attachment, URL", "note": "Returning from the in-app browser restores the draft and confirms it with a banner. Seven field types across 23-05 and 23-06."}, "23-07": {"s": "app", "sn": "S/N 23", "title": "Form: validation errors", "note": "Errors appear on Submit, with a summary at top and a message plus icon under each field. Save draft never validates."}, "23-08": {"s": "app", "sn": "S/N 23", "title": "Form: submitted, read-only", "note": "Values replace inputs; the action bar shows a lock with a text label."}, "23-09": {"s": "app", "sn": "S/N 23", "title": "Support role: completed tab", "note": "Rounded segmented toggle reused from Missions | VFTP. Rule: edit only while incomplete."}, "23-10": {"s": "app", "sn": "S/N 23", "title": "Support role: reminder push", "note": "Sent on the rule set in the Portal (N days after event, or a fixed day each month). Tapping opens 23-09 on Incomplete."}, "23-11": {"s": "app", "sn": "S/N 23", "title": "Volunteer: in-app notifications", "note": "Opened from the bell. Each type has its own icon and label (full centre on the cross-cutting page)."}, "23-12": {"s": "app", "sn": "S/N 23", "title": "Volunteer: Profile → My Feedback", "note": "New \"My Feedback\" tab beside My Posts and My Comments. Perfect ratings show the points awarded."}, "23-13": {"s": "app", "sn": "S/N 23", "title": "Volunteer: feedback detail", "note": "Rule shown: only fields the template marks shareable. Role, deploy-again and attachment stay internal."}, "23-14": {"s": "app", "sn": "S/N 23", "title": "Roster at largest text size", "note": "At 200% text, rows stack vertically, pills wrap to their own line and the action becomes a full-width button."}, "23-15": {"s": "por", "sn": "S/N 23", "title": "Portal: template library", "note": "Templates are tagged to event types; the event card picks one (23-17). Archived versions stay linked to past feedback."}, "23-16": {"s": "por", "sn": "S/N 23", "title": "Portal: template builder", "note": "Seven field types; each has Required, Share with volunteer and conditional show/hide. The phone preview uses the app's components."}, "23-17": {"s": "por", "sn": "S/N 23", "title": "Portal: event card support settings", "note": "Event-card tabs are shared by S/N 23, 25, 28, 29 and 30. Multi-select search assigns support users per slot."}, "23-18": {"s": "por", "sn": "S/N 23", "title": "Portal: feedback register", "note": "Filters for event, slot, author, subject, status and date. Export applies current filters. Row detail marks which fields are shared."}, "24-01": {"s": "app", "sn": "S/N 24", "title": "Recognition feed", "note": "Opened from the What's New tile. Recognition reuses the Forum post card with cover media."}, "24-02": {"s": "app", "sn": "S/N 24", "title": "Post detail", "note": "Carousel, rich text, link preview and file attachments. Reaction bar stays pinned."}, "24-03": {"s": "app", "sn": "S/N 24", "title": "Viewer: PDF", "note": "In-app viewer; the volunteer never leaves the app. Pinch or buttons to zoom."}, "24-04": {"s": "app", "sn": "S/N 24", "title": "Viewer: Office document", "note": "Word, Excel and PowerPoint files are converted to PDF for viewing; the original stays downloadable. Toast confirms the download."}, "24-05": {"s": "app", "sn": "S/N 24", "title": "Viewer: audio (MP3)", "note": "Learn-card gradient reused. Skip 15 s buttons are labelled; transcript for accessibility."}, "24-06": {"s": "app", "sn": "S/N 24", "title": "Viewer: video (MP4)", "note": "Captions toggle is on by default and labelled as text, not just an icon."}, "24-07": {"s": "app", "sn": "S/N 24", "title": "Comment sheet", "note": "The author sees their own comment as Pending review until a moderator approves it."}, "24-08": {"s": "app", "sn": "S/N 24", "title": "Share sheet", "note": "Native share sheet with a deep-link preview. Link opens the post in the app, or the store if not installed."}, "24-09": {"s": "app", "sn": "S/N 24", "title": "Empty state", "note": "Same composition as the Forum empty states."}, "24-10": {"s": "app", "sn": "S/N 24", "title": "Media processing state", "note": "Shown while transcoding; text content remains readable."}, "24-11": {"s": "app", "sn": "S/N 24", "title": "Feed at largest text size", "note": "Counters stack and gain text labels at 200% so meaning isn't carried by icons."}, "24-12": {"s": "por", "sn": "S/N 24", "title": "Portal: post editor", "note": "Every file is scanned on upload (Scanning → Clean / Blocked). Blocked files can't be published."}, "24-13": {"s": "por", "sn": "S/N 24", "title": "Portal: moderation and reach", "note": "Approve or reject in bulk; flagged comments are highlighted. Reach is reported per post with trending rank."}, "25-01": {"s": "app", "sn": "S/N 25", "title": "Discover Events: named lock", "note": "Existing padlock overlay. The caption now names the first unmet prerequisite instead of a task count."}, "25-02": {"s": "app", "sn": "S/N 25", "title": "Time-slot card: three states", "note": "Eligible · locked with a one-line reason · admin override marked with a small pill."}, "25-03": {"s": "app", "sn": "S/N 25", "title": "Locked detail sheet", "note": "Each unmet rule deep-links to the module or event that satisfies it. Met rules are ticked and greyed."}, "25-04": {"s": "app", "sn": "S/N 25", "title": "Lock sheet at largest text size", "note": "At 200% the sheet opens full-screen; status uses a text symbol and the words, not colour."}, "25-05": {"s": "por", "sn": "S/N 25", "title": "Portal: eligibility rules builder", "note": "Predicate rows joined in AND/OR groups. The plain-language summary is generated and is what volunteers see paraphrased in 25-03."}, "25-06": {"s": "por", "sn": "S/N 25", "title": "Portal: override and ineligible attempts", "note": "Overrides need a reason and are audited. The report lists who tried to register and which rule stopped them."}, "26-01": {"s": "app", "sn": "S/N 26", "title": "Reward detail", "note": "From Home → Store. \"Mailable\" tag appears only on items the Portal marks mailable."}, "26-02": {"s": "app", "sn": "S/N 26", "title": "Choose how to receive", "note": "Non-mailable items skip this step and go straight to self-collect."}, "26-03": {"s": "app", "sn": "S/N 26", "title": "Address form with postal lookup", "note": "Postal code fills block and street. Validation runs as each field loses focus."}, "26-04": {"s": "app", "sn": "S/N 26", "title": "Confirmation", "note": "Mascot confirmation in the empty-state style, with a reference number."}, "26-05": {"s": "app", "sn": "S/N 26", "title": "My redemptions", "note": "Under Store. Newest first; status pill shows the current step."}, "26-06": {"s": "app", "sn": "S/N 26", "title": "Status timeline", "note": "Five-step timeline. \"I have received it\" moves the order to Acknowledged."}, "26-07": {"s": "app", "sn": "S/N 26", "title": "Receipt reminder", "note": "Sent N days after Dispatched (Portal setting). \"Not yet\" alerts the fulfilment team."}, "26-08": {"s": "app", "sn": "S/N 26", "title": "Address form at largest text size", "note": "Find button drops below the field; the error text keeps its icon at 200%."}, "26-09": {"s": "por", "sn": "S/N 26", "title": "Portal: store item settings", "note": "Mailable toggle, stock and the note volunteers see in 26-02. Reminder timing drives 26-07."}, "26-10": {"s": "por", "sn": "S/N 26", "title": "Portal: fulfilment queue", "note": "Bulk status update, CSV for the mailing house, and a row drawer with editable address (audited) and points history."}, "27-01": {"s": "app", "sn": "S/N 27", "title": "Public profile (another volunteer)", "note": "Stat tiles reused from Home. Only shareable feedback fields appear. ⋯ opens Block / Report."}, "27-02": {"s": "app", "sn": "S/N 27", "title": "Own profile: edit", "note": "From Forum → Profile. Accent colour is limited to the app palette. Private hides everything but the Referrer name."}, "27-03": {"s": "app", "sn": "S/N 27", "title": "Search by Referrer name", "note": "Forum search gains a People tab. Private profiles appear by name only, without Follow."}, "27-04": {"s": "app", "sn": "S/N 27", "title": "Entry points: Leaderboard, Forum post", "note": "Names and avatars on the Leaderboard and on Forum posts become tappable (ring = tap target)."}, "27-05": {"s": "app", "sn": "S/N 27", "title": "Friends: Following / Followers", "note": "Opened from the Following count on Profile (where \"Following: 0 Topics\" sits today)."}, "27-06": {"s": "app", "sn": "S/N 27", "title": "Friends' accomplishment feed", "note": "Rolling window set in the Portal (27-10). Celebrate is a single reaction; no comments."}, "27-07": {"s": "app", "sn": "S/N 27", "title": "Home toasts: friend vs non-friend", "note": "Friend: avatar, \"Your friend\" label, Celebrate. Non-friend: generic icon; name only if their profile is public."}, "27-08": {"s": "app", "sn": "S/N 27", "title": "Shared profile link preview", "note": "Open Graph card as it unfurls in chat apps (WhatsApp, Telegram). Shared via the native sheet shown in 24-08."}, "27-09": {"s": "app", "sn": "S/N 27", "title": "Public profile at largest text size", "note": "Stat tiles become a labelled list at 200%."}, "27-10": {"s": "por", "sn": "S/N 27", "title": "Portal: profile settings, reports, engagement", "note": "Feed window drives the \"last 14 days\" note in 27-06. Hidden profiles fall back to the default mascot avatar and name."}, "28-01": {"s": "app", "sn": "S/N 28", "title": "Month view", "note": "List | Calendar toggle reuses the Missions | VFTP control. Status dots differ by shape as well as colour."}, "28-02": {"s": "app", "sn": "S/N 28", "title": "Agenda list view", "note": "Left bar = category colour from the Portal legend. Status pill on the right."}, "28-03": {"s": "app", "sn": "S/N 28", "title": "Filter sheet", "note": "The button shows the result count before applying."}, "28-04": {"s": "app", "sn": "S/N 28", "title": "Event detail: add to my calendar", "note": "Writes to the phone's calendar after the OS permission prompt. Changes in CPFV update the entry."}, "28-05": {"s": "app", "sn": "S/N 28", "title": "SHL deployment, distinct style", "note": "Deployments get a hatched, dashed card plus a text label so they read as duties, not optional events."}, "28-06": {"s": "app", "sn": "S/N 28", "title": "Empty month", "note": "Reuses the My Activities empty-state illustration and button."}, "28-07": {"s": "app", "sn": "S/N 28", "title": "Agenda at largest text size", "note": "At 200% the month grid is replaced by the agenda; dates are written out in full."}, "28-08": {"s": "por", "sn": "S/N 28", "title": "Portal: event calendar settings", "note": "Per-event toggle and type. The type sets both the colour and, for SHL, the distinct card style."}, "28-09": {"s": "por", "sn": "S/N 28", "title": "Portal: calendar legend editor", "note": "Drag to order the legend shown in the app (28-01). Each type sets a colour and card style."}, "29-01": {"s": "app", "sn": "S/N 29", "title": "Home: no-show warning", "note": "Warning banner in tab-bar yellow, with dark text for contrast. The counter wording comes from the Portal policy."}, "29-02": {"s": "app", "sn": "S/N 29", "title": "Event: marked No-show", "note": "History entry states the rule and gives a way to dispute."}, "29-03": {"s": "app", "sn": "S/N 29", "title": "Blocked: registration paused", "note": "Dimmed-card pattern with a red-orange padlock, distinct from the yellow prerequisite lock. Lift date shown on every card."}, "29-04": {"s": "app", "sn": "S/N 29", "title": "Notifications: warning, block, lift", "note": "Three notices, each with its own symbol and a plain statement of what changed."}, "29-05": {"s": "app", "sn": "S/N 29", "title": "Profile: no-show history", "note": "Under Forum → Profile. The counter resets after the block is lifted."}, "29-06": {"s": "app", "sn": "S/N 29", "title": "Blocked at largest text size", "note": "Disabled button keeps a text reason."}, "29-07": {"s": "por", "sn": "S/N 29", "title": "Portal: penalty policy editor", "note": "One policy per event type. The preview sentence is the same text volunteers see in 29-01 and 29-02."}, "29-08": {"s": "por", "sn": "S/N 29", "title": "Portal: event attendance with penalty", "note": "Per-event toggle. Editing a status recalculates counters and blocks straight away, with a before → after preview."}, "29-09": {"s": "por", "sn": "S/N 29", "title": "Portal: history report and manual lift", "note": "Report has the six data points: no-show dates, block, lift, running block count, counter and reset marker. Manual lift needs a reason."}, "30-01": {"s": "por", "sn": "S/N 30", "title": "Portal: groups list and create (dynamic)", "note": "Static or dynamic. The dynamic rule builder reuses the S/N 25 predicate rows and shows a live match count."}, "30-02": {"s": "por", "sn": "S/N 30", "title": "Portal: add members by CSV", "note": "CSV is validated before anything is written. Errors can be downloaded, fixed and re-uploaded."}, "30-03": {"s": "por", "sn": "S/N 30", "title": "Portal: restrict registration, audit, reports", "note": "The non-member setting switches between the two app options. Both are designed so the Authority can choose."}, "30-04": {"s": "app", "sn": "S/N 30", "title": "Restricted event: member view", "note": "Members see a normal card with a small group chip."}, "30-05": {"s": "app", "sn": "S/N 30", "title": "Non-member, option A: hidden", "note": "Option A: the event simply doesn't appear. Deep links open the message in 30-07."}, "30-06": {"s": "app", "sn": "S/N 30", "title": "Non-member, option B: labelled", "note": "Option B: listed, with a \"By invitation\" chip and no Register button."}, "30-07": {"s": "app", "sn": "S/N 30", "title": "Non-member opens the event", "note": "A clear reason and a next step instead of a disabled button."}, "30-08": {"s": "app", "sn": "S/N 30", "title": "Invitation message at largest text size", "note": "The chip keeps its envelope symbol so it reads without colour."}, "X-01": {"s": "app", "sn": "Cross-cutting", "title": "Notification centre", "note": "Each type has a fixed icon, colour and text label."}, "X-02": {"s": "app", "sn": "Cross-cutting", "title": "Settings → Privacy", "note": "Mirrors the options in 27-02; toggles have text labels."}, "X-03": {"s": "app", "sn": "Cross-cutting", "title": "Settings → Language", "note": "Placeholder for the four languages; names in their own script."}, "X-04": {"s": "app", "sn": "Cross-cutting", "title": "Error state", "note": "Empty-state layout with an error mascot and a reference for the helpdesk."}, "X-05": {"s": "app", "sn": "Cross-cutting", "title": "Offline state", "note": "Offline banner; cached content stays readable. Drafts (23-06) save locally and sync later."}};
